using Shopify.Blazor.Cli.Catalogue;
using Xunit;

namespace Shopify.Blazor.Cli.Tests;

/// <summary>
/// Tests for the component catalogue reader.
/// </summary>
/// <remarks>
/// The catalogue is generated by another workstream, so the tests build their own from the
/// documented schema. That is the point: if the shape the CLI reads drifts from the shape the
/// schema documents, these tests fail rather than the command silently finding zero components.
/// </remarks>
public sealed class PolarisCatalogueTests
{
    /// <summary>The fixture catalogue, written to the schema in docs/templates-plan.md.</summary>
    public const string FixtureJson = """
        {
          "generatedBy": "tools/generate-component-reference.py",
          "components": [
            {
              "wrapper": "PolarisButton",
              "element": "s-button",
              "namespace": "Polaris.Blazor.Components",
              "summary": "Wraps <s-button>.",
              "parameters": [
                { "name": "Variant", "type": "PolarisButtonVariant" },
                { "name": "OnClick", "type": "EventCallback<PolarisEventArgs>" },
                { "name": "ChildContent", "type": "RenderFragment?" }
              ],
              "events": ["click"],
              "slots": ["primary-action", "secondary-actions"]
            },
            {
              "wrapper": "PolarisDataTable",
              "element": "s-data-table",
              "namespace": "Polaris.Blazor.Components",
              "summary": "Wraps <s-data-table>.",
              "parameters": [
                { "name": "Heading", "type": "string" }
              ],
              "events": [],
              "slots": []
            },
            {
              "wrapper": "PolarisBanner",
              "element": "s-banner",
              "namespace": "Polaris.Blazor.Components",
              "summary": "Wraps <s-banner>.",
              "parameters": [
                { "name": "Tone", "type": "PolarisTone" }
              ],
              "events": [],
              "slots": ["primary-action"]
            }
          ]
        }
        """;

    private static PolarisCatalogue Catalogue() => PolarisCatalogue.Parse(FixtureJson);

    [Fact]
    public void Parses_every_component_from_the_documented_schema()
    {
        // A naming policy or property-name change here produces an empty catalogue, which would
        // make 'add component' claim every component is unknown.
        var catalogue = Catalogue();

        Assert.Equal("tools/generate-component-reference.py", catalogue.GeneratedBy);
        Assert.Equal(3, catalogue.Components.Count);
        Assert.Equal("s-data-table", catalogue.Find("DataTable")!.Element);
    }

    [Fact]
    public void Finds_a_component_with_or_without_the_polaris_prefix()
    {
        // A developer types 'Button' about as often as 'PolarisButton'; refusing one of them is a
        // pointless error.
        var catalogue = Catalogue();

        Assert.NotNull(catalogue.Find("Button"));
        Assert.NotNull(catalogue.Find("polarisbutton"));
        Assert.Equal("PolarisButton", catalogue.Find("BUTTON")!.Wrapper);
    }

    [Fact]
    public void Suggests_the_closest_names_for_an_unknown_component()
    {
        // 'add component DataTablet' should point at DataTable rather than dumping 60 names.
        var suggestions = Catalogue().Suggest("DataTablet");

        Assert.Contains("PolarisDataTable", suggestions);
    }

    [Fact]
    public void Reports_a_catalogue_that_is_not_json()
    {
        // The generator is another workstream; a half-written file must produce a message, not a
        // stack trace.
        var exception = Assert.Throws<CatalogueException>(() => PolarisCatalogue.Parse("{ not json"));

        Assert.Contains("not valid JSON", exception.Message);
    }

    [Fact]
    public void Tolerates_a_component_with_no_parameters_arrays()
    {
        // Missing optional arrays are the most likely difference between generator versions, and
        // they must not be fatal.
        var catalogue = PolarisCatalogue.Parse("""
            { "generatedBy": "x", "components": [ { "wrapper": "PolarisDivider" } ] }
            """);

        var component = catalogue.Find("Divider");

        Assert.NotNull(component);
        Assert.Empty(component!.Parameters);
        Assert.Empty(component.Events);
        Assert.Empty(component.Slots);
    }
}
